/**
 * Seeded BSP dungeon generator.
 *
 * - Recursively splits a fixed W x H area into leaves.
 * - Split ratio is clamped to [0.35, 0.65] of the parent extent.
 * - Leaves are at least MIN_LEAF cells wide and tall (splitting stops
 *   when neither axis can host two MIN_LEAF-sized halves).
 * - Each leaf gets exactly one room, inset by a 2-cell margin.
 * - Every internal node connects one room from its left subtree with one
 *   room from its right subtree via an L-shaped corridor between room
 *   centers, recursing up the tree -> the whole floor graph is connected.
 */

export const MAP_W = 64;
export const MAP_H = 48;
export const MIN_LEAF = 10;
export const ROOM_MARGIN = 2;
export const SPLIT_RATIO_MIN = 0.35;
export const SPLIT_RATIO_MAX = 0.65;

export interface Rect {
  x: number;
  y: number;
  w: number;
  h: number;
}

export class BSPTree {
  rect: Rect;
  left: BSPTree | null = null;
  right: BSPTree | null = null;
  room: Rect | null = null;

  constructor(rect: Rect) {
    this.rect = rect;
  }

  get isLeaf(): boolean {
    return this.left === null && this.right === null;
  }
}

export interface Dungeon {
  seed: number;
  width: number;
  height: number;
  tiles: string[][]; // [y][x], '#' wall, '.' floor
  rooms: Rect[];
  leaves: BSPTree[];
  root: BSPTree;
  hash: string; // FNV-1a hash of the tile map (hex)
}

/* ------------------------------------------------------------------ */
/* Seeded RNG (mulberry32)                                             */
/* ------------------------------------------------------------------ */

export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function intBetween(rng: () => number, min: number, max: number): number {
  return min + Math.floor(rng() * (max - min + 1));
}

/* ------------------------------------------------------------------ */
// BSP splitting
/* ------------------------------------------------------------------ */

/** True when the rectangle can still be split into two >= MIN_LEAF halves. */
function canSplit(r: Rect): boolean {
  return r.w >= MIN_LEAF * 2 || r.h >= MIN_LEAF * 2;
}

function split(node: BSPTree, rng: () => number): void {
  if (!canSplit(node.rect)) return;

  const { x, y, w, h } = node.rect;
  // Choose axis: forced if only one fits, otherwise random.
  let horizontal: boolean;
  if (w >= MIN_LEAF * 2 && h >= MIN_LEAF * 2) horizontal = rng() < 0.5;
  else horizontal = w >= MIN_LEAF * 2;

  if (horizontal) {
    const lo = Math.max(MIN_LEAF, Math.ceil(w * SPLIT_RATIO_MIN));
    const hi = Math.min(w - MIN_LEAF, Math.floor(w * SPLIT_RATIO_MAX));
    const cut = intBetween(rng, lo, hi);
    node.left = new BSPTree({ x, y, w: cut, h });
    node.right = new BSPTree({ x: x + cut, y, w: w - cut, h });
  } else {
    const lo = Math.max(MIN_LEAF, Math.ceil(h * SPLIT_RATIO_MIN));
    const hi = Math.min(h - MIN_LEAF, Math.floor(h * SPLIT_RATIO_MAX));
    const cut = intBetween(rng, lo, hi);
    node.left = new BSPTree({ x, y, w, h: cut });
    node.right = new BSPTree({ x, y: y + cut, w, h: h - cut });
  }

  split(node.left!, rng);
  split(node.right!, rng);
}

/* ------------------------------------------------------------------ */
// Rooms & corridors
/* ------------------------------------------------------------------ */

function placeRoom(leaf: BSPTree, rng: () => number): void {
  const m = ROOM_MARGIN;
  const innerX = leaf.rect.x + m;
  const innerY = leaf.rect.y + m;
  const innerW = leaf.rect.w - m * 2; // >= 6 for MIN_LEAF=10
  const innerH = leaf.rect.h - m * 2;
  const rw = intBetween(rng, 3, innerW);
  const rh = intBetween(rng, 3, innerH);
  leaf.room = {
    x: intBetween(rng, innerX, innerX + innerW - rw),
    y: intBetween(rng, innerY, innerY + innerH - rh),
    w: rw,
    h: rh,
  };
}

function carveRect(tiles: string[][], r: Rect): void {
  for (let y = r.y; y < r.y + r.h; y++) {
    for (let x = r.x; x < r.x + r.w; x++) {
      tiles[y][x] = '.';
    }
  }
}

function center(r: Rect): { cx: number; cy: number } {
  return { cx: r.x + (r.w >> 1), cy: r.y + (r.h >> 1) };
}

function carveCorridor(tiles: string[][], a: Rect, b: Rect, rng: () => number): void {
  const p = center(a);
  const q = center(b);
  const horizFirst = rng() < 0.5;
  const hRange = { from: Math.min(p.cx, q.cx), to: Math.max(p.cx, q.cx) };
  const vRange = { from: Math.min(p.cy, q.cy), to: Math.max(p.cy, q.cy) };

  const doHoriz = (yy: number) => {
    for (let x = hRange.from; x <= hRange.to; x++) tiles[yy][x] = '.';
  };
  const doVert = (xx: number) => {
    for (let y = vRange.from; y <= vRange.to; y++) tiles[y][xx] = '.';
  };

  if (horizFirst) {
    doHoriz(p.cy);
    doVert(q.cx);
  } else {
    doVert(p.cy);
    doHoriz(q.cy);
  }
}

/** One room out of the subtree rooted at `node` (any deterministic pick). */
function pickRoom(node: BSPTree): Rect | null {
  if (node.isLeaf) return node.room;
  return pickRoom(node.left!) ?? pickRoom(node.right!);
}

function connectSiblings(
  node: BSPTree,
  tiles: string[][],
  rng: () => number,
): void {
  if (node.isLeaf) return;
  connectSiblings(node.left!, tiles, rng);
  connectSiblings(node.right!, tiles, rng);
  const a = pickRoom(node.left!);
  const b = pickRoom(node.right!);
  if (a && b) carveCorridor(tiles, a, b, rng);
}

/* ------------------------------------------------------------------ */
// Hashing & public API
/* ------------------------------------------------------------------ */

export function hashTiles(tiles: string[][]): string {
  let h = 0x811c9dc5;
  for (const row of tiles) {
    for (const ch of row.join('')) {
      h ^= ch.charCodeAt(0);
      h = Math.imul(h, 0x01000193);
    }
  }
  return (h >>> 0).toString(16).padStart(8, '0');
}

function collectLeaves(node: BSPTree, acc: BSPTree[]): BSPTree[] {
  if (node.isLeaf) acc.push(node);
  else collectLeaves(node.left!, acc), collectLeaves(node.right!, acc);
  return acc;
}

export function generateDungeon(seed: number): Dungeon {
  const rng = mulberry32(seed);

  const root = new BSPTree({ x: 0, y: 0, w: MAP_W, h: MAP_H });
  split(root, rng);

  const leaves = collectLeaves(root, []);
  for (const leaf of leaves) placeRoom(leaf, rng);

  const tiles: string[][] = Array.from({ length: MAP_H }, () =>
    Array.from({ length: MAP_W }, () => '#'),
  );
  for (const leaf of leaves) carveRect(tiles, leaf.room!);
  connectSiblings(root, tiles, rng);

  const rooms = leaves.map((l) => l.room!);
  return {
    seed,
    width: MAP_W,
    height: MAP_H,
    tiles,
    rooms,
    leaves,
    root,
    hash: hashTiles(tiles),
  };
}

/* ------------------------------------------------------------------ */
// ASCII rendering
/* ------------------------------------------------------------------ */

export function renderAscii(d: Dungeon): string {
  return d.tiles.map((row) => row.join('')).join('\n');
}

