result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/bsp.test.ts", "content": "import { describe, it, expect } from 'vitest';
import {
  generateDungeon,
  hashTiles,
  MAP_W,
  MAP_H,
  MIN_LEAF,
  ROOM_MARGIN,
  type Rect,
  type Dungeon,
} from './bsp.js';

const SEEDS = Array.from({ length: 12 }, (_, i) => i + 1);

function rectsOverlap(a: Rect, b: Rect): boolean {
  return a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;
}

function rectInside(inner: Rect, outer: Rect): boolean {
  return (
    inner.x >= outer.x &&
    inner.y >= outer.y &&
    inner.x + inner.w <= outer.x + outer.w &&
    inner.y + inner.h <= outer.y + outer.h
  );
}

/** Flood fill over 4-connected floor tiles; returns reachable floor count. */
function floodFill(d: Dungeon): number {
  let start: { x: number; y: number } | null = null;
  let totalFloor = 0;
  for (let y = 0; y < d.height; y++) {
    for (let x = 0; x < d.width; x++) {
      if (d.tiles[y][x] === '.') {
        totalFloor++;
        if (!start) start = { x, y };
      }
    }
  }
  if (!start) return 0;

  const seen = new Set<number>();
  const queue = [start];
  seen.add(start.y * d.width + start.x);
  while (queue.length > 0) {
    const { x, y } = queue.pop()!;
    const neighbors = [
      { x: x - 1, y },
      { x: x + 1, y },
      { x, y: y - 1 },
      { x, y: y + 1 },
    ];
    for (const n of neighbors) {
      if (n.x < 0 || n.y < 0 || n.x >= d.width || n.y >= d.height) continue;
      const key = n.y * d.width + n.x;
      if (seen.has(key) || d.tiles[n.y][n.x] !== '.') continue;
      seen.add(key);
      queue.push(n);
    }
  }
  return seen.size;
}

describe.each(SEEDS.map((s) => [s]))('seed %i', (seed) => {
  const d = generateDungeon(seed);

  it('has the fixed 64x48 dimensions', () => {
    expect(d.width).toBe(MAP_W);
    expect(d.height).toBe(MAP_H);
    expect(d.tiles).toHaveLength(MAP_H);
    for (const row of d.tiles) expect(row).toHaveLength(MAP_W);
  });

  it('places every room inside its leaf with at least the 2-cell margin', () => {
    expect(d.rooms).toHaveLength(d.leaves.length);
    for (const leaf of d.leaves) {
      const room = leaf.room!;
      expect(room.w).toBeGreaterThan(0);
      expect(room.h).toBeGreaterThan(0);
      // Room strictly inside leaf inset by ROOM_MARGIN.
      expect(room.x).toBeGreaterThanOrEqual(leaf.rect.x + ROOM_MARGIN);
      expect(room.y).toBeGreaterThanOrEqual(leaf.rect.y + ROOM_MARGIN);
      expect(room.x + room.w).toBeLessThanOrEqual(leaf.rect.x + leaf.rect.w - ROOM_MARGIN);
      expect(room.y + room.h).toBeLessThanOrEqual(leaf.rect.y + leaf.rect.h - ROOM_MARGIN);
      // And therefore inside the leaf itself (and the map).
      expect(rectInside(room, leaf.rect)).toBe(true);
      expect(rectInside(leaf.rect, { x: 0, y: 0, w: MAP_W, h: MAP_H })).toBe(true);
    }
  });

  it('has no overlapping rooms', () => {
    for (let i = 0; i < d.rooms.length; i++) {
      for (let j = i + 1; j < d.rooms.length; j++) {
        expect(rectsOverlap(d.rooms[i], d.rooms[j])).toBe(false);
      }
    }
  });

  it('has a fully connected floor graph (flood fill covers all floors)', () => {
    let totalFloor = 0;
    for (const row of d.tiles) for (const t of row) if (t === '.') totalFloor++;
    expect(totalFloor).toBeGreaterThan(0);
    expect(floodFill(d)).toBe(totalFloor);
  });

  it('has between 8 and 64 leaves', () => {
    expect(d.leaves.length).toBeGreaterThanOrEqual(8);
    expect(d.leaves.length).toBeLessThanOrEqual(64);
  });

  it('respects the minimum leaf size', () => {
    for (const leaf of d.leaves) {
      expect(leaf.rect.w).toBeGreaterThanOrEqual(MIN_LEAF);
      expect(leaf.rect.h).toBeGreaterThanOrEqual(MIN_LEAF);
    }
  });

  it('is deterministic for the same seed (identical map hash)', () => {
    const again = generateDungeon(seed);
    expect(hashTiles(again.tiles)).toBe(d.hash);
    expect(renderHashStable(again)).toBe(renderHashStable(d));
  });

  function renderHashStable(dd: Dungeon): string {
    return dd.hash + ':' + dd.rooms.map((r) => `${r.x},${r.y},${r.w},${r.h}`).join(';');
  }

  it('carves exactly its rooms plus corridors as floor (rooms are floor)', () => {
    for (const r of d.rooms) {
      for (let y = r.y; y < r.y + r.h; y++) {
        for (let x = r.x; x < r.x + r.w; x++) {
          expect(d.tiles[y][x]).toBe('.');
        }
      }
    }
  });
});

describe('cross-seed properties', () => {
  it('produces stable per-seed hashes across repeated runs', () => {
    const firstRun = SEEDS.map((s) => generateDungeon(s).hash);
    const secondRun = SEEDS.map((s) => generateDungeon(s).hash);
    expect(secondRun).toEqual(firstRun);
    // Hashes should be recorded for every seed.
    for (const h of firstRun) expect(h).toMatch(/^[0-9a-f]{8}$/);
  });

  it('never lets two different seeds share a room layout hash trivially broken', () => {
    // Different seeds must generate independently (no cross-contamination).
    const a = generateDungeon(7);
    const b = generateDungeon(8);
    const c = generateDungeon(7);
    expect(c.hash).toBe(a.hash);
    expect(c.hash).not.toBeUndefined();
    void b;
  });
});
"})
